(sh) => {                                               // the mint belly (the only green-dominant texels) glows from inside
        sh.uniforms.uJunGlow = glow; sh.uniforms.uPower = U.uPower;
        sh.fragmentShader = 'uniform float uJunGlow, uPower;\n' + sh.fragmentShader.replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
          float junBelly = smoothstep(.02, .13, diffuseColor.g - max(diffuseColor.r, diffuseColor.b));
          totalEmissiveRadiance += vec3(.2, .9, .55) * junBelly * uJunGlow * (.1 + (1. - uPower) * 1.2);`);
      }

